import {USER_CONFIG,MODULES,PLANS,ZONES,CLIENTS,LEADS,FLEET,INTEGRATIONS} from './moviads-data.js';

const KEY='moviads-central-demo-v1', PASS='MOVIADS2027';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('es-PA',{style:'currency',currency:'USD',minimumFractionDigits:Number.isInteger(n)?0:2,maximumFractionDigits:Number.isInteger(n)?0:2}).format(n||0);
const num=n=>new Intl.NumberFormat('es-PA').format(n||0);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=new Date();
function monthValue(d=today){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
const monthName=(v)=>new Intl.DateTimeFormat('es-PA',{month:'long',year:'numeric'}).format(new Date(`${v}-01T12:00:00`));
const initialAssignments=()=>{
 const out={}; for(let i=1;i<=20;i++)out[`MA-${String(i).padStart(2,'0')}`]=Array(8).fill(null);
 const active=CLIENTS.filter(c=>c.stage==='Activo'); let p=0;
 active.forEach(c=>{const size=PLANS.find(x=>x.id===c.plan)?.screens||1;for(let j=0;j<size;j++){let n=0;while(n<20&&out[`MA-${String(((p+n)%20)+1).padStart(2,'0')}`].every(Boolean))n++; const id=`MA-${String(((p+n)%20)+1).padStart(2,'0')}`; const slot=out[id].findIndex(x=>!x);if(slot>=0)out[id][slot]={client:c.name,plan:c.plan,kind:'vendido'};p=(p+n+1)%20;}});
 return out;
};
const fresh=()=>({month:monthValue(),profile:'ana',view:'inicio',assignments:{[monthValue()]:initialAssignments()},sales:[],campaigns:[],invoices:[],decisions:{},messages:[{id:'m1',from:'Ana Victoria',to:'Eric',subject:'Lead · Clínica Sonrisa',body:'La doctora pregunta si podemos medir cuántas personas agendan desde el QR. ¿Quién prepara la propuesta?',ref:'Clínica Sonrisa',time:'Hoy, 8:48 a. m.'},{id:'m2',from:'Emanuel',to:'Contabilidad',subject:'Gasto fijo · combustible',body:'¿Me confirmas si este valor incluye el ajuste del mes?',ref:'Combustible · noviembre',time:'Ayer, 4:12 p. m.'}],threads:[],autonomy:{ana:'Consultar antes de escribir',eric:'Consultar antes de escribir',emanuel:'Autónomo'},leadHeat:{},appointments:[],sync:{},customer:'Tropigas'});
let state; try{state={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')};}catch{state=fresh()}
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const allProfiles=()=>[...USER_CONFIG.profiles,...(state.extraUsers||[])];
const profile=()=>allProfiles().find(p=>p.id===state.profile)||USER_CONFIG.profiles[0];
const owner=()=>profile().access==='owner';
const canMargin=()=>owner();
const canExport=()=>owner();
const canApprove=()=>owner()||profile().access==='sales';
const canEdit=()=>owner()||profile().access==='sales';
function ensureMonth(m){if(!state.assignments[m])state.assignments[m]=initialAssignments();return state.assignments[m]}
function allocationFor(planId,m=state.month){const map=ensureMonth(m),plan=PLANS.find(p=>p.id===planId),ids=Object.keys(map);let result=[];for(const id of ids){let slot=map[id].findIndex(x=>!x);if(slot>=0&&result.length<plan.screens)result.push([id,slot]);}return result}
function packageAvailable(plan,m=state.month){const map=ensureMonth(m);const free=Object.values(map).reduce((a,row)=>a+row.filter(x=>!x).length,0);return Math.floor(free/plan.screens)}
function soldCount(m=state.month){return Object.values(ensureMonth(m)).reduce((a,row)=>a+row.filter(x=>x?.kind==='vendido').length,0)}
function reservedCount(m=state.month){return Object.values(ensureMonth(m)).reduce((a,row)=>a+row.filter(x=>x?.kind==='reservado').length,0)}
const activeCampaigns=()=>CLIENTS.filter(c=>c.stage==='Activo').length+state.campaigns.length;
const pendingReceivable=()=>CLIENTS.reduce((n,c)=>n+(c.stage==='Activo'&&!['McDonald’s','Cochez','Nexa Solutions'].includes(c.name)?c.revenue:0),0);
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)}
function openModal(title,body,wide=false){$('#overlay-root').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><div><span class="kicker">MOVIADS CENTRAL</span><h2>${esc(title)}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">×</button></header><div class="modal-body">${body}</div></section></div>`;document.body.classList.add('modal-open')}
function closeModal(){ $('#overlay-root').innerHTML='';document.body.classList.remove('modal-open') }
const navList=()=>MODULES.filter(([id])=>{
 if(profile().access==='finance')return ['inicio','finanzas','mensajes'].includes(id);
 if(profile().access==='service')return ['inicio','clientes','medicion','flota','mensajes'].includes(id);
 if(profile().access==='sales')return ['inicio','inventario','programacion','clientes','medicion','agentes','flota','mensajes'].includes(id);
 return true;
});
function render(){
 const p=profile(); if(p.access==='finance'&&!['inicio','finanzas','mensajes'].includes(state.view))state.view='finanzas';
 if(p.access==='service'&&['finanzas','equipo','conexiones','agentes'].includes(state.view))state.view='clientes';
 const active=MODULES.find(x=>x[0]===state.view)||MODULES[0];
 $('#app').innerHTML=`<div class="app-shell"><header class="topbar"><a class="brand" href="#inicio" data-view="inicio"><img src="./assets/logo-moviads.svg" alt=""><span class="brand-wordmark">MOVIADS</span><span class="brand-divider"></span><span class="product-name">Central</span></a><span class="example-label">Datos de ejemplo</span><div class="top-actions"><label class="profile-select"><span>Usuario</span><select id="profile-select">${allProfiles().map(x=>`<option value="${x.id}" ${x.id===state.profile?'selected':''}>${esc(x.name)}${x.name===x.role?'':' · '+esc(x.role)}</option>`).join('')}</select></label><button class="assistant-top" data-action="assistant"><span class="assistant-glyph">⌕</span><span>Asistente MOVIADS</span><kbd>⌘ K</kbd></button></div></header>
 <nav class="module-nav" aria-label="Secciones">${navList().map(([id,label])=>`<button class="module-tab ${id===state.view?'active':''}" data-view="${id}"><span class="tab-index">${String(MODULES.findIndex(m=>m[0]===id)+1).padStart(2,'0')}</span>${label}</button>`).join('')}</nav>
 <main class="main-area"><div class="page-top"><div><div class="breadcrumb">MOVIADS CENTRAL <span>/</span> ${active[1].toUpperCase()}</div><h1>${active[1]}</h1><p>${active[2]}</p></div><div class="page-actions">${owner()?'<button class="button quiet" data-action="reset">Restablecer datos de ejemplo</button>':''}</div></div>${viewContent()}</main>
 <footer class="app-footer"><span>OPERACIÓN · CIUDAD DE PANAMÁ</span><span>Prototipo navegable · Datos de ejemplo</span></footer></div>`;
}
function viewContent(){switch(state.view){case'inicio':return home();case'inventario':return inventory();case'programacion':return scheduling();case'clientes':return clients();case'medicion':return measurement();case'agentes':return agents();case'flota':return fleet();case'finanzas':return finance();case'mensajes':return messages();case'equipo':return team();case'conexiones':return connections();default:return home()}}
function home(){let offline=FLEET.filter(x=>x.status!=='online').length;const recs=[{id:'d1',text:'Tropigas registra 94% de sus reproducciones con 6 días de campaña. Proponer extensión.',action:'Renovar Tropigas',go:'clientes'},{id:'d2',text:'La pantalla 07 lleva 3 horas sin reportar. Revisar señal y unidad.',action:'Ver unidad MA-07',go:'flota'},{id:'d3',text:`Quedan ${packageAvailable(PLANS[1])} paquetes METRO disponibles para ${monthName(state.month)}.`,action:'Abrir inventario',go:'inventario'}];
return `<section class="morning-band"><div class="morning-copy"><div class="eyebrow-light">MIÉRCOLES · RESUMEN DE OPERACIÓN</div><h2>Lo que pasó desde el cierre</h2><p>Actividad registrada hasta hoy, 8:50 a. m.</p></div><div class="morning-grid"><div><span>Leads nuevos</span><strong>${LEADS.length}</strong><small>${LEADS.filter(l=>l.heat==='Caliente').length} con interés alto</small></div><div><span>Campañas al aire</span><strong>${activeCampaigns()}</strong><small>En distribución</small></div><div><span>Ocupación de red</span><strong>${Math.round((soldCount()+reservedCount())/160*100)}%</strong><small>${soldCount()} de 160 espacios vendidos</small></div><div><span>Unidades sin señal</span><strong>${offline}</strong><small>1 apagada · 1 sin reporte</small></div></div></section>
<div class="home-columns"><section class="section-block"><div class="section-heading"><div><span class="kicker">DECISIONES SUGERIDAS</span><h2>Bandeja de revisión</h2></div><span class="count">${recs.filter(r=>!state.decisions[r.id]).length} pendientes</span></div><div class="decision-list">${recs.map(r=>state.decisions[r.id]?`<article class="decision-row resolved"><span class="decision-number">✓</span><div><p>${esc(r.text)}</p><small>Decisión ${state.decisions[r.id]}</small></div></article>`:`<article class="decision-row"><span class="decision-number">${String(recs.indexOf(r)+1).padStart(2,'0')}</span><div><p>${esc(r.text)}</p><small>Propuesta del sistema · ${r.go==='flota'?'Flota':'Comercial'}</small></div><div class="decision-actions"><button class="button primary small" data-action="decision" data-id="${r.id}" data-value="Aprobada" data-go="${r.go}">Aprobar</button><button class="button quiet small" data-action="decision" data-id="${r.id}" data-value="Descartada">Descartar</button></div></article>`).join('')}</div></section>
<aside class="right-stack"><section class="section-block compact"><div class="section-heading"><div><span class="kicker">COBRANZA</span><h2>Por cobrar</h2></div><button class="text-link" data-view="finanzas">Ver finanzas ↗</button></div><strong class="large-figure">${money(pendingReceivable())}</strong><p class="subline">4 facturas · 2 próximas a vencer</p><div class="thin-meter"><i style="width:68%"></i></div><div class="meter-labels"><span>68% al día</span><span>Noviembre</span></div></section><section class="section-block compact"><div class="section-heading"><div><span class="kicker">RED EN VIVO</span><h2>Estado de las pantallas</h2></div><button class="text-link" data-view="flota">Ver flota ↗</button></div><div class="status-line"><span class="status-mark good"></span><span>Encendidas y reportando</span><strong>18</strong></div><div class="status-line"><span class="status-mark off"></span><span>Apagada</span><strong>1</strong></div><div class="status-line"><span class="status-mark issue"></span><span>Sin señal reciente</span><strong>1</strong></div><div class="sparkline-wrap"><svg viewBox="0 0 420 52" role="img" aria-label="Actividad de la red durante el día"><path d="M0 43 L25 39 50 42 75 25 100 29 125 15 150 22 175 17 200 8 225 15 250 11 275 19 300 12 325 17 350 8 375 13 400 4 420 7" fill="none" stroke="#15A595" stroke-width="1.5"/><path d="M0 50 L0 43 L25 39 50 42 75 25 100 29 125 15 150 22 175 17 200 8 225 15 250 11 275 19 300 12 325 17 350 8 375 13 400 4 420 7 L420 50Z" fill="#15A595" opacity=".08"/></svg></div><div class="meter-labels"><span>6:00 a. m.</span><span>Actividad de red</span><span>9:00 a. m.</span></div></section></aside></div>
<section class="section-block home-lower"><div class="section-heading"><div><span class="kicker">OPERACIÓN</span><h2>Seguimiento de hoy</h2></div><span class="muted">Actualizado hace 4 min</span></div><div class="home-activity"><button data-view="programacion"><span class="activity-icon">01</span><span><strong>Distribución de pautas</strong><small>${CLIENTS.filter(c=>c.stage==='Activo').length} campañas listas para enviar a OnSign</small></span><b>Revisar ↗</b></button><button data-view="agentes"><span class="activity-icon">02</span><span><strong>Respuestas de prospección</strong><small>${LEADS.filter(l=>l.heat==='Caliente').length} leads con interés alto requieren seguimiento</small></span><b>Abrir ↗</b></button><button data-view="finanzas"><span class="activity-icon">03</span><span><strong>Facturación de noviembre</strong><small>4 clientes con saldo pendiente</small></span><b>Ver ↗</b></button></div></section>`}

function inventory(){const map=ensureMonth(state.month),free=160-soldCount(state.month)-reservedCount(state.month);return `<section class="inventory-intro"><div><span class="kicker">CAPACIDAD DE RED</span><div class="capacity-title"><strong>20</strong><span>pantallas</span><i></i><strong>8</strong><span>espacios por loop</span></div><p>Un espacio equivale a una marca del loop. Cada unidad tiene dos caras LED. A plena ocupación, la capacidad estimada se acerca a 2.8 millones de reproducciones al mes.</p></div><label class="month-picker">PERÍODO<input type="month" id="inventory-month" value="${state.month}"></label></section><div class="inventory-summary"><div><span>Espacios vendidos</span><strong>${soldCount()}</strong><small>de 160 · ${reservedCount()} reservados</small></div><div><span>Espacios disponibles</span><strong>${free}</strong><small>incluye inventario no reservado</small></div><div><span>Reproducciones estimadas</span><strong>${num(soldCount()*45*13*30)}</strong><small>proyección · 13 h × 30 días</small></div><button class="button primary" data-action="sale">Simular venta +</button></div><section class="section-block"><div class="section-heading"><div><span class="kicker">PAQUETES MOVIADS</span><h2>Disponibilidad en ${esc(monthName(state.month))}</h2></div><span class="quiet-note">Precios de ejemplo · Cotización según duración</span></div><div class="plan-grid">${PLANS.map(p=>`<div class="plan-cell"><span>${p.id}</span><strong>${packageAvailable(p)}</strong><small>${p.screens} ${p.screens===1?'pantalla':'pantallas'} por paquete</small><div class="plan-track"><i style="width:${Math.min(100,Math.max(8,packageAvailable(p)*10))}%"></i></div></div>`).join('')}</div></section><section class="section-block matrix-section"><div class="section-heading"><div><span class="kicker">INVENTARIO DE RED</span><h2>Pantalla por espacio</h2></div><div class="legend"><span><i class="legend-swatch sold"></i>Vendido</span><span><i class="legend-swatch reserved"></i>Reservado</span><span><i class="legend-swatch free"></i>Libre</span></div></div><div class="table-scroll"><table class="matrix-table"><thead><tr><th>Pantalla</th>${Array.from({length:8},(_,i)=>`<th>ESP ${String(i+1).padStart(2,'0')}</th>`).join('')}<th>Red</th></tr></thead><tbody>${Object.entries(map).map(([id,row])=>`<tr><th><span class="unit-code">${id}</span><small>${FLEET[Number(id.slice(-2))-1].zone}</small></th>${row.map((x,j)=>`<td><button class="space-cell ${x?x.kind:'free'}" title="${x?`${x.client} · ${x.plan}`:'Espacio disponible'}" data-action="slot" data-unit="${id}" data-slot="${j}">${x?esc(x.client):'Libre'}</button></td>`).join('')}<td class="row-capacity">${row.filter(Boolean).length}/8</td></tr>`).join('')}</tbody></table></div><div class="mobile-matrix">${Object.entries(map).map(([id,row])=>`<article class="mobile-screen-card"><header><strong>${id}</strong><span>${FLEET[Number(id.slice(-2))-1].zone}</span><small>${row.filter(Boolean).length}/8 espacios</small></header><div>${row.map((x,j)=>`<button class="space-cell ${x?x.kind:'free'}" data-action="slot" data-unit="${id}" data-slot="${j}"><span>${String(j+1).padStart(2,'0')}</span>${x?esc(x.client):'Libre'}</button>`).join('')}</div></article>`).join('')}</div><p class="footnote">Estimación de referencia: un anuncio de 10 segundos en loop de 8 marcas se reproduce cerca de 45 veces por hora en cada pantalla.</p></section>`}

function scheduling(){let campaigns=[...CLIENTS.filter(c=>c.stage==='Activo').map((c,i)=>({id:`PA-${String(i+21).padStart(3,'0')}`,client:c.name,creative:c.creative,plays:c.plays,target:c.target,plan:c.plan,sync:state.sync[`PA-${String(i+21).padStart(3,'0')}`]||(i===2?'Pendiente de envío':'Sincronizado'),progress:Math.round(c.plays/c.target*100),zone:c.zones[0]})),...state.campaigns.map(c=>({...c,sync:state.sync[c.id]||c.sync}))];return `<section class="section-block schedule-banner"><div><span class="kicker">DISTRIBUCIÓN AUTOMÁTICA</span><h2>De la pauta contratada a la red</h2><p>El sistema propone una frecuencia por pantalla y franja, y deja el paquete listo para sincronizar con OnSign.</p></div><button class="button primary" data-action="campaign">Crear pauta +</button></section><div class="schedule-stats"><div><span>Al aire hoy</span><strong>${campaigns.length}</strong></div><div><span>Sincronizadas</span><strong>${campaigns.filter(c=>c.sync==='Sincronizado').length}</strong></div><div><span>Requieren revisión</span><strong>${campaigns.filter(c=>c.progress<94||c.sync!=='Sincronizado').length}</strong></div><div><span>Frecuencia base</span><strong>45 <small>/h</small></strong></div></div><section class="section-block"><div class="section-heading"><div><span class="kicker">PAUTAS ACTIVAS</span><h2>Entrega y sincronización</h2></div><span class="quiet-note">10 s por marca · 8 marcas máximo por loop</span></div><div class="campaign-list">${campaigns.map(c=>`<article class="campaign-row"><div class="campaign-id">${esc(c.id)}<small>${esc(c.plan)}</small></div><div class="campaign-client"><strong>${esc(c.client)}</strong><small>${esc(c.creative||'Creativo pendiente')} · ${esc(c.zone||'Cobertura contratada')}</small></div><div class="campaign-progress"><div><span>Reproducciones entregadas</span><strong>${num(c.plays)} / ${num(c.target)}</strong></div><div class="progress-line"><i class="${c.progress<90?'behind':''}" style="width:${Math.min(c.progress,100)}%"></i></div></div><span class="sync-state ${c.sync==='Sincronizado'?'ok':''}">${esc(c.sync)}</span><button class="button quiet small" data-action="${c.sync==='Sincronizado'?'pauta':'sync'}" data-id="${esc(c.id)}">${c.sync==='Sincronizado'?'Ver pauta':'Enviar a OnSign'}</button></article>`).join('')}</div></section><section class="section-block schedule-grid"><div><span class="kicker">DISTRIBUCIÓN PROPUESTA</span><h2>Por franja de operación</h2><div class="hour-chart">${[['6–9 a. m.',38],['9–12 p. m.',57],['12–3 p. m.',68],['3–6 p. m.',91],['6–9 p. m.',73]].map(x=>`<div><i style="height:${x[1]}%"></i><span>${x[0]}</span></div>`).join('')}</div></div><div class="schedule-note"><span class="kicker">REGLA DE ENTREGA</span><p>El sistema reparte las reproducciones contratadas entre las pantallas del plan, los días de vigencia y las horas activas. OnSign mantiene el control de reproducción en pantalla.</p><button class="text-link" data-view="conexiones">Revisar conexión OnSign ↗</button></div></section>`}

function clients(){let list=CLIENTS;return `<section class="section-block client-toolbar"><div class="filter-tabs"><button class="filter-tab active" data-filter="all">Todos <b>${list.length}</b></button>${['Activo','Propuesta','Prospecto'].map(s=>`<button class="filter-tab" data-filter="${s}">${s}</button>`).join('')}</div><label class="search-box"><span>⌕</span><input id="client-search" placeholder="Buscar cliente"></label></section><section class="client-list" id="client-list">${list.map(c=>clientRow(c)).join('')}</section>`}
function clientRow(c){return `<article class="client-row" data-client-row data-name="${esc(c.name.toLowerCase())}" data-stage="${c.stage}"><span class="client-monogram">${c.name.slice(0,2).toUpperCase()}</span><div class="client-main"><strong>${esc(c.name)}</strong><small>${esc(c.contact)} · ${esc(c.history)}</small></div><span class="stage-label ${c.stage==='Activo'?'active':c.stage==='Propuesta'?'proposal':''}">${esc(c.stage)}</span><div class="client-campaign"><strong>${esc(c.campaign||'Sin campaña activa')}</strong><small>${esc(c.plan)}${c.period?' · '+esc(c.period):''}</small></div>${canMargin()?`<div class="client-value"><strong>${money(c.revenue)}</strong><small>facturación</small></div>`:''}<button class="text-link" data-action="client" data-id="${c.id}">Abrir ficha ↗</button></article>`}

function measurement(){const client=CLIENTS.find(c=>c.name===state.customer)||CLIENTS[0];const currentPlan=PLANS.find(p=>p.id===client.plan)||PLANS[2],planIndex=PLANS.findIndex(p=>p.id===client.plan),nextPlan=PLANS[Math.max(0,planIndex-1)],projectedScans=client.scans?Math.round(client.scans*nextPlan.screens/currentPlan.screens):0;const heat=[22,38,31,48,62,78,94,82,66,54,72,91,84,60,46,39,31,28,43,58,74,61,42,25];const points=[[33,48,'Balboa'],[42,37,'Obarrio'],[50,52,'San Francisco'],[63,61,'Costa del Este'],[69,76,'Tocumen'],[52,31,'El Cangrejo'],[30,59,'Paitilla'],[46,24,'Albrook'],[57,40,'Vía España'],[74,54,'Juan Díaz']];return `<div class="measurement-top"><section class="map-panel"><div class="map-heading"><div><span class="kicker">TRAZADO DE RED</span><h2>Ciudad de Panamá</h2></div><span class="map-caption">Esquema ilustrativo</span></div><div class="city-map"><svg viewBox="0 0 800 460" preserveAspectRatio="xMidYMid slice" aria-label="Mapa esquemático de Ciudad de Panamá"><rect width="800" height="460" fill="#eff5f7"/><path d="M-20 373 Q75 326 151 344T294 321T432 322T562 281T828 238L830 470H-20Z" fill="#c9e4ea"/><path d="M44 310 C138 273 196 288 280 231 S410 210 478 179 S601 171 733 91" fill="none" stroke="#173A7A" stroke-width="4" opacity=".78"/><path d="M69 117 C146 167 231 137 321 193 S490 237 620 207 S730 229 790 279" fill="none" stroke="#6E9BD8" stroke-width="3" opacity=".75"/><path d="M184 405 C240 335 271 275 331 225 S409 165 449 65" fill="none" stroke="#15A595" stroke-width="3" opacity=".82"/><path d="M90 200 L237 192 320 231 400 208 478 179 562 193 673 160 M276 60 L303 143 321 193 290 280 270 360 M463 40 L449 130 478 179 467 276 509 361" fill="none" stroke="#b5c8d2" stroke-width="1.5"/><g fill="#4F5867" font-family="IBM Plex Sans" font-size="13"><text x="57" y="281">Balboa</text><text x="330" y="160">Obarrio</text><text x="417" y="244">San Francisco</text><text x="578" y="230">Costa del Este</text><text x="658" y="302">Tocumen</text><text x="191" y="183">Albrook</text><text x="350" y="281">Paitilla</text><text x="501" y="150">Vía España</text><text x="260" y="107">El Cangrejo</text></g><g>${points.map((p,i)=>`<g transform="translate(${p[0]*8},${p[1]*4.3})"><circle r="9" fill="#0B1F4A" opacity=".12"/><circle r="5" fill="#15A595" stroke="#fff" stroke-width="2"><title>${p[2]} · unidad ${String(i+1).padStart(2,'0')}</title></circle></g>`).join('')}</g><g class="map-route-dots">${Array.from({length:30},(_,i)=>`<circle cx="${80+i*21}" cy="${350-Math.sin(i*.52)*45}" r="2.3" fill="#6E9BD8" opacity=".6"/>`).join('')}</g></svg><div class="map-legend"><span><i class="map-dot"></i>Pantalla en ruta</span><span><i class="map-line"></i>Corredor ilustrativo</span><small>El trazado no representa GPS en tiempo real</small></div></div></section><aside class="measurement-aside"><section class="section-block compact"><span class="kicker">REPRODUCCIONES · NOVIEMBRE</span><strong class="metric-large">${num(CLIENTS.reduce((a,c)=>a+c.plays,0))}</strong><small>registradas en la red</small><div class="sparkline-wrap big"><svg viewBox="0 0 320 70"><path d="M0 58 L22 48 45 51 68 34 91 38 114 25 137 31 160 12 183 23 206 19 229 7 252 18 275 12 298 5 320 9" fill="none" stroke="#15A595" stroke-width="2"/></svg></div><span class="comparison">+8.4% frente a octubre</span></section><section class="section-block compact"><span class="kicker">REGISTRO PARA AUDITORÍA</span><div class="audit-facts"><span>Fecha y hora<strong>Por reproducción</strong></span><span>Equipo<strong>20 unidades</strong></span><span>Coordenada<strong>GPS registrado</strong></span></div></section></aside></div><div class="measurement-columns"><section class="section-block"><div class="section-heading"><div><span class="kicker">ACTIVIDAD POR ZONA</span><h2>Reproducciones y escaneos</h2></div><span class="quiet-note">Noviembre 2026</span></div><div class="zone-list">${[['San Francisco',42800,219],['Costa del Este',37600,184],['Obarrio',33900,176],['Vía España',29800,161],['Tocumen',24700,131],['Balboa y Paitilla',21600,97]].map(z=>`<div><span>${z[0]}</span><div class="zone-bar"><i style="width:${z[1]/45000*100}%"></i></div><strong>${num(z[1])}</strong><small>${z[2]} QR</small></div>`).join('')}</div><div class="hour-heat"><span class="kicker">MAPA DE CALOR · POR HORA</span><div>${heat.map((v,i)=>`<i title="${i}:00 · índice ${v}" style="--heat:${v/100}"></i>`).join('')}</div><div class="heat-labels"><span>12 a. m.</span><span>6 a. m.</span><span>12 p. m.</span><span>6 p. m.</span><span>11 p. m.</span></div></div></section><section class="section-block qr-panel"><div class="section-heading"><div><span class="kicker">MEDICIÓN DE QR</span><h2>Escaneos y acciones</h2></div></div><label class="field-label">CAMPAÑA<select id="customer-select">${CLIENTS.filter(c=>c.stage==='Activo').map(c=>`<option ${c.name===client.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="qr-numbers"><div><span>Escaneos</span><strong>${num(client.scans)}</strong><small>por pantalla, zona y hora</small></div><div><span>Acción final</span><strong>${num(client.actions)}</strong><small>formularios o clics</small></div></div><div class="conversion-row"><span>Tasa de acción</span><strong>${client.scans?Math.round(client.actions/client.scans*100):0}%</strong><i style="width:${client.scans?client.actions/client.scans*100:0}%"></i></div><div class="scan-screen-list"><span class="kicker">MUESTRA DE ESCANEOS POR PANTALLA</span><div><b>MA-03</b><span>Obarrio · 5:00 p. m.</span><strong>68</strong></div><div><b>MA-11</b><span>Costa del Este · 7:00 p. m.</span><strong>54</strong></div><div><b>MA-14</b><span>Vía España · 6:00 p. m.</span><strong>43</strong></div></div><p class="projection"><b>Proyección</b> Si ${esc(client.name)} pasa de ${client.plan} a ${nextPlan.id}, la proyección es de ${num(projectedScans)} escaneos el próximo mes, según el histórico de zonas y frecuencia.</p><button class="button primary full" data-action="report" data-client="${esc(client.name)}">Generar reporte del cliente</button></section></div>`}

function agents(){const type=state.agentType||'anunciantes';const sectors=type==='conductores'?['Conductores de plataforma','Conductores Uber','Conductores independientes']:['Clínicas dentales','Restaurantes y cafeterías','Ferreterías','Concesionarios'];const leads=LEADS.filter(l=>type==='conductores'?l.sector==='Conductor':l.sector!=='Conductor');const heat=l=>state.leadHeat[l.id]||l.heat;return `<section class="agent-hero"><div><span class="kicker light">DOS FLUJOS DE PROSPECCIÓN</span><h2>Buscar. Conversar. Clasificar.</h2><p>Revisa la conversación y decide cuánta autonomía tiene el agente por usuario.</p></div><div class="agent-tabs"><button class="${type==='anunciantes'?'active':''}" data-action="agent-type" data-value="anunciantes">Anunciantes</button><button class="${type==='conductores'?'active':''}" data-action="agent-type" data-value="conductores">Conductores</button></div></section><div class="agent-controls"><label class="field-label">RUBRO<select id="agent-sector">${sectors.map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field-label">ZONA<select id="agent-zone">${ZONES.map(z=>`<option ${z==='Obarrio'?'selected':''}>${z}</option>`).join('')}</select></label><button class="button primary" data-action="run-agent">Buscar prospectos</button><button class="button quiet" data-action="simulate-notice">Simular aviso</button></div><div class="autonomy-banner"><div><span class="kicker">TU CONFIGURACIÓN</span><strong>${esc(profile().name)} · <span id="autonomy-current">${esc(state.autonomy[state.profile]||profile().autonomy)}</span></strong></div><label class="field-label">AUTONOMÍA<select id="autonomy-select">${['Consultar antes de escribir','Autónomo','Revisar respuestas','Manual'].map(a=>`<option ${a===(state.autonomy[state.profile]||profile().autonomy)?'selected':''}>${a}</option>`).join('')}</select></label><label class="field-label">AVISAR POR<select id="notice-channel"><option>WhatsApp</option><option ${(state.channels?.[state.profile]||profile().channel)==='Correo'?'selected':''}>Correo</option></select></label><button class="text-link" data-action="agent-rules">Editar reglas ↗</button></div><section class="kanban"><div class="kanban-top"><div><span class="kicker">CONVERSACIONES</span><h2>Estado del prospecto</h2></div><span class="quiet-note">${leads.length} registros de ejemplo · mueve con selector</span></div><div class="kanban-columns">${['Frío','Tibio','Caliente','Reunión agendada'].map(stage=>`<div class="kanban-col"><header><span>${stage}</span><strong>${leads.filter(l=>heat(l)===stage).length}</strong></header>${leads.filter(l=>heat(l)===stage).map(l=>`<article class="lead-card"><div class="lead-card-top"><strong>${esc(l.name)}</strong><button data-action="lead-detail" data-id="${l.id}" aria-label="Ver conversación">↗</button></div><span>${esc(l.sector)} · ${esc(l.zone)}</span><p>${esc(l.intent)}</p><small>${esc(l.last)} · ${esc(l.channel)}</small><label class="lead-stage-select">CLASIFICACIÓN<select data-lead-heat="${l.id}">${['Frío','Tibio','Caliente','Reunión agendada'].map(x=>`<option ${x===heat(l)?'selected':''}>${x}</option>`).join('')}</select></label>${l.budget?`<div class="lead-budget"><span>${l.seconds} s · ${l.plan}</span><strong>${money(l.budget)}</strong></div>`:''}<button class="text-link" data-action="lead-detail" data-id="${l.id}">Ver conversación ↗</button></article>`).join('')||'<p class="empty-column">Sin prospectos en esta etapa</p>'}</div>`).join('')}</div></section>`}

function fleet(){return `<section class="fleet-hero"><div><span class="kicker light">OPERACIÓN DE PANTALLAS</span><h2>20 unidades en cobertura</h2><p>Estado de la pantalla, actividad registrada y zonas recorridas.</p></div><div class="fleet-total"><strong>18</strong><span>encendidas</span><small>1 apagada · 1 sin señal</small></div></section><div class="fleet-toolbar"><div class="filter-tabs"><button class="filter-tab active" data-fleet-filter="all">Todas · 20</button><button class="filter-tab" data-fleet-filter="online">En línea · 18</button><button class="filter-tab" data-fleet-filter="off">Apagadas · 1</button><button class="filter-tab" data-fleet-filter="offline">Sin señal · 1</button></div><label class="search-box"><span>⌕</span><input id="fleet-search" placeholder="Buscar unidad o conductor"></label></div><section class="fleet-grid" id="fleet-grid">${FLEET.map(f=>`<article class="fleet-card" data-fleet-item data-status="${f.status}" data-search="${f.id.toLowerCase()} ${f.driver.toLowerCase()} ${f.car.toLowerCase()}"><div class="fleet-photo"><img src="./assets/${f.image}" alt="Vehículo de la flota MOVIADS"><span class="screen-state ${f.status}"><i></i>${f.status==='online'?'Pantalla encendida':f.status==='off'?'Pantalla apagada':'Sin señal'}</span><b>${f.id}</b></div><div class="fleet-card-body"><div class="fleet-car"><div><strong>${esc(f.car)}</strong><small>${esc(f.driver)}</small></div><button class="icon-btn small-icon" data-action="unit" data-id="${f.id}" aria-label="Ver unidad">↗</button></div><div class="fleet-facts"><span>Horas activas<strong>${f.hours.toFixed(1)} h</strong></span><span>Recorrido<strong>${num(f.km)} km</strong></span><span>Zona reciente<strong>${esc(f.zone)}</strong></span><span>Conducción<strong>${esc(f.behavior)}</strong></span></div><div class="fleet-card-foot"><span>Incentivo de ejemplo</span><strong>${money(f.incentive)}</strong></div></div></article>`).join('')}</section>`}

function finance(){const revenue=CLIENTS.reduce((a,c)=>a+c.revenue,0)+state.campaigns.reduce((a,c)=>a+c.value,0),cost=CLIENTS.reduce((a,c)=>a+c.cost,0);return `<div class="finance-top"><section class="section-block finance-primary"><span class="kicker">INGRESOS · NOVIEMBRE 2026</span><strong>${money(revenue)}</strong><div class="finance-trend"><span>Por cobrar</span><b>${money(pendingReceivable())}</b><i>4 documentos pendientes</i></div><button class="text-link" data-action="ask-accountant" data-amount="Ingresos de noviembre · ${money(revenue)}">Preguntar al contable ↗</button></section><section class="section-block finance-secondary"><span class="kicker">GASTOS FIJOS · EJEMPLO</span><strong>${money(3850)}</strong><p>Combustible · conectividad · mantenimiento</p><button class="text-link" data-action="ask-accountant" data-amount="Gastos fijos · noviembre · ${money(3850)}">Preguntar al contable ↗</button></section>${canMargin()?`<section class="section-block finance-secondary"><span class="kicker">MARGEN DE CAMPAÑAS</span><strong>${money(revenue-cost)}</strong><p>Ingresos ${money(revenue)} · costos directos ${money(cost)}</p><button class="text-link" data-action="ask-accountant" data-amount="Margen de campañas · noviembre · ${money(revenue-cost)}">Preguntar al contable ↗</button></section>`:''}</div><section class="section-block invoice-section"><div class="section-heading"><div><span class="kicker">CUENTAS POR CLIENTE</span><h2>Facturación del mes</h2></div><span class="quiet-note">Importes y documentos de ejemplo</span></div><div class="invoice-list">${CLIENTS.filter(c=>c.stage==='Activo').map((c,i)=>{const paid=i===1||i===3||i===5,issued=state.invoices.some(x=>x.client===c.name);return `<article class="invoice-row"><div class="invoice-date">${String(26-i).padStart(2,'0')}<small>NOV</small></div><div class="invoice-client"><strong>${esc(c.name)}</strong><small>Factura FV-2026-${String(441+i).padStart(4,'0')} · ${esc(c.plan)}</small></div><div class="invoice-status ${paid?'paid':''}">${paid?'Pagada':issued?'Emitida · pendiente':'Pendiente'}</div><strong class="invoice-amount">${money(c.revenue)}</strong>${paid||issued?`<button class="text-link" data-action="invoice-view" data-id="${c.id}">Ver factura ↗</button>`:`<button class="button primary small" data-action="invoice" data-id="${c.id}">Emitir factura</button>`}<button class="icon-btn" title="Preguntar al contable" data-action="ask-accountant" data-amount="Factura de ${esc(c.name)} · ${money(c.revenue)}">↗</button></article>`}).join('')}</div><p class="footnote">La emisión muestra una representación de factura electrónica con CUFE y QR. No conecta con la DGI.</p></section><section class="finance-bottom"><div class="section-block"><div class="section-heading"><div><span class="kicker">INGRESOS</span><h2>Actividad mensual</h2></div></div><div class="revenue-chart">${[58,73,66,84,69,92,77,100,82,88,75,94].map((n,i)=>`<div><i style="height:${n}%"></i><span>${['D','E','F','M','A','M','J','J','A','S','O','N'][i]}</span></div>`).join('')}</div></div><div class="section-block">${canMargin()?`<span class="kicker">MEZCLA DE CAMPAÑAS</span><h2>Costos y contribución</h2><div class="cost-line"><span>Costos directos de pauta</span><strong>${money(cost)}</strong></div><div class="cost-track"><i style="width:${cost/revenue*100}%"></i></div><div class="cost-line"><span>Contribución de campañas</span><strong>${money(revenue-cost)}</strong></div>`:profile().access==='finance'?`<span class="kicker">COSTOS DE OPERACIÓN</span><h2>Costos directos</h2><div class="cost-line"><span>Costos directos de pauta</span><strong>${money(cost)}</strong></div><div class="cost-line"><span>Gastos fijos de operación</span><strong>${money(3850)}</strong></div><button class="text-link" data-action="ask-accountant" data-amount="Costos directos · ${money(cost)}">Preguntar al contable ↗</button>`:`<span class="kicker">SEGUIMIENTO DE COBROS</span><h2>Próximos vencimientos</h2><p>McDonald’s · vence el 28 de noviembre</p><p>Denago EV · vence el 30 de noviembre</p><p>Revisa la bandeja de facturas para ver el estado.`}</div></section>`}

function messages(){const all=[...state.messages,...state.threads].sort((a,b)=>b.id.localeCompare(a.id));return `<section class="messages-layout"><aside class="thread-list"><div class="section-heading"><div><span class="kicker">BANDEJA INTERNA</span><h2>Conversaciones</h2></div><button class="icon-btn" data-action="new-message" aria-label="Nuevo mensaje">＋</button></div>${all.map((m,i)=>`<button class="thread-item ${i===0?'selected':''}" data-action="thread" data-id="${m.id}"><span class="thread-avatar">${m.from.slice(0,1)}</span><span><strong>${esc(m.subject)}</strong><small>${esc(m.ref)} · ${esc(m.time)}</small><p>${esc(m.body)}</p></span></button>`).join('')}</aside><section class="conversation"><div class="conversation-head"><div><span class="kicker">HILO INTERNO</span><h2>${esc(all[0]?.subject||'Conversación nueva')}</h2></div><span class="linked-record">Vinculado a ${esc(all[0]?.ref||'un registro')}</span></div><div class="message-bubble"><small>${esc(all[0]?.from||'Ana Victoria')} · ${esc(all[0]?.time||'Ahora')}</small><p>${esc(all[0]?.body||'Escribe una nota para el equipo.')}</p><span class="linked-record">Registro · ${esc(all[0]?.ref||'Sin vínculo')}</span></div><form id="message-form" class="message-compose"><label for="message-input">RESPONDER AL HILO</label><textarea id="message-input" placeholder="Escribe un mensaje para el equipo" required></textarea><div><label class="field-label">VINCULAR A<select id="message-ref">${['Clínica Sonrisa','Tropigas','Combustible · noviembre','McDonald’s','Pantalla MA-07'].map(x=>`<option>${x}</option>`).join('')}</select></label><button class="button primary">Enviar mensaje</button></div></form></section></section>`}

function team(){return `<section class="team-intro"><div><span class="kicker">CONTROL DE ACCESO</span><h2>Roles y datos protegidos</h2><p>Los permisos determinan qué puede consultar y cambiar cada usuario.</p></div><button class="button primary" data-action="add-user">Agregar usuario +</button></section><section class="section-block permissions"><div class="section-heading"><div><span class="kicker">MATRIZ DE PERMISOS</span><h2>Rol contra permiso</h2></div><span class="quiet-note">Los socios tienen acceso total</span></div><div class="table-scroll"><table class="permission-table"><thead><tr><th>PERMISO</th>${allProfiles().map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${USER_CONFIG.permissionRows.map(([name,desc,key])=>`<tr><th>${name}<small>${desc}</small></th>${allProfiles().map(p=>{let yes=p.access==='owner'||(key==='ver')||(key==='editar'&&['sales','finance'].includes(p.access))||(key==='exportar'&&p.access==='owner');return `<td><span class="permission ${yes?'yes':'no'}">${yes?'✓':'×'}</span></td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="permission-cards">${allProfiles().map(p=>`<article><header><strong>${esc(p.name)}</strong><small>${esc(p.role)}</small></header>${USER_CONFIG.permissionRows.map(([name,desc,key])=>{const yes=p.access==='owner'||key==='ver'||(key==='editar'&&['sales','finance'].includes(p.access))||(key==='exportar'&&p.access==='owner');return `<div class="permission-card-row"><span>${name}</span><b class="${yes?'yes':'no'}">${yes?'Permitido':'Sin acceso'}</b></div>`}).join('')}</article>`).join('')}</div></section><section class="section-block user-list"><div class="section-heading"><div><span class="kicker">USUARIOS ACTIVOS</span><h2>Personas con acceso</h2></div></div>${allProfiles().map(p=>`<div class="user-row"><span class="user-avatar">${p.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.role)} · ${esc(p.autonomy)}</small></div><span class="user-state">Activo</span><button class="text-link" data-action="user-access" data-id="${p.id}">Permisos ↗</button></div>`).join('')}</section><section class="export-panel"><div><span class="kicker light">PORTABILIDAD</span><h2>Tus datos son tuyos</h2><p>Descarga un archivo con los datos de ejemplo y los cambios que hiciste en esta sesión.</p></div><button class="button light-button" data-action="export-all" ${canExport()?'':'disabled'}>Exportar todos mis datos ↓</button></section>`}

function connections(){return `<section class="connections-intro"><span class="kicker">SERVICIOS Y SISTEMAS</span><h2>Un espacio para la operación</h2><p>Estado representado para el prototipo. Conectar estos servicios requiere configuración y credenciales de MOVIADS.</p></section><section class="connection-list">${INTEGRATIONS.map((i,n)=>`<article class="connection-row"><div class="connection-mark">${['G','W','O','D'][n]}</div><div class="connection-name"><strong>${esc(i.name)}</strong><small>${esc(i.sub)}</small></div><div class="connection-state"><span class="state-bar ${n===2||n===3?'demo':''}"></span><strong>${esc(state.sync[i.name]||i.state)}</strong><small>Última actividad · ${esc(i.last)}</small></div><button class="button ${n===2||n===3?'quiet':'outline'} small" data-action="integration" data-name="${esc(i.name)}">${n===2||n===3?'Ver detalles':'Conectar'}</button></article>`).join('')}</section><section class="section-block integration-notes"><div><span class="kicker">GOOGLE WORKSPACE</span><p>Gmail, Calendar, Meet y Drive aparecen juntos para apoyar correos, reuniones y archivos asociados al cliente.</p></div><div><span class="kicker">ONSIGN</span><p>Las pautas se prepararían en MOVIADS Central y se enviarían al sistema de pantallas tras validar la conexión disponible.</p></div><div><span class="kicker">FACTURA DGI</span><p>La vista de factura representa el documento fiscal con folio, CUFE y QR; la autorización real no está conectada.</p></div></section>`}

function saleModal(){openModal('Simular venta',`<p class="modal-intro">Al confirmar, el sistema reserva un espacio por pantalla del plan para el período seleccionado.</p><form id="sale-form" class="form-grid"><label class="field-label span-two">CLIENTE<select name="client" required>${CLIENTS.map(c=>`<option>${esc(c.name)}</option>`).join('')}<option>Nuevo cliente de ejemplo</option></select></label><label class="field-label">PLAN<select name="plan">${PLANS.map(p=>`<option value="${p.id}">${p.id} · ${p.screens} ${p.screens===1?'pantalla':'pantallas'}</option>`).join('')}</select></label><label class="field-label">MES<input name="month" type="month" value="${state.month}" required></label><label class="field-label">FECHA DE INICIO<input name="start" type="date" value="${state.month}-01"></label><label class="field-label">FECHA DE CIERRE<input name="end" type="date" value="${state.month}-${new Date(Number(state.month.slice(0,4)),Number(state.month.slice(5,7)),0).getDate()}"></label><label class="field-label">INVERSIÓN DE EJEMPLO<input name="value" type="number" min="0" step="50" value="3200"></label><div class="form-submit span-two"><span>Disponibles en el período: <b id="sale-availability">elige un plan</b></span><button class="button primary">Confirmar venta simulada</button></div></form>`)}
function demoCampaigns(){return [...CLIENTS.filter(c=>c.stage==='Activo').map((c,i)=>({id:`PA-${String(i+21).padStart(3,'0')}`,client:c.name,creative:c.creative,plays:c.plays,target:c.target,plan:c.plan,sync:state.sync[`PA-${String(i+21).padStart(3,'0')}`]||(i===2?'Pendiente de envío':'Sincronizado'),zone:c.zones[0]})),...state.campaigns.map(c=>({...c,sync:state.sync[c.id]||c.sync}))]}
function pautaModal(id){const c=demoCampaigns().find(x=>x.id===id);if(!c)return;const plan=PLANS.find(p=>p.id===c.plan)||{screens:1};const n=plan.screens||1;const franjas=[['6 a 9 a. m.',38],['9 a 12 m.',57],['12 a 3 p. m.',68],['3 a 6 p. m.',91],['6 a 9 p. m.',73]];const tot=franjas.reduce((s,f)=>s+f[1],0);const target=Number(c.target)||0;const porPantalla=Math.round(target/n);const pesos=Array.from({length:n},(_,i)=>1+0.16*Math.sin(i*1.7+0.4));const sp=pesos.reduce((s,x)=>s+x,0);const fila=k=>{const base=target*pesos[k]/sp;return franjas.map(f=>Math.round(base*f[1]/tot))};const zonas=['Paitilla','Obarrio','Calle 50','Costa del Este','San Francisco','Vía España','El Cangrejo','Bella Vista','Albrook','Juan Díaz','Condado del Rey','Marbella','Punta Pacífica','Tumba Muerto','San Miguelito','Vía Israel','Brisas del Golf'];const filas=Array.from({length:n},(_,i)=>{const v=fila(i);return `<tr><th>MA-${String(i+1).padStart(2,'0')}<small>${esc(zonas[i%zonas.length])}</small></th>${v.map(x=>`<td>${num(x)}</td>`).join('')}<td><b>${num(v.reduce((s,x)=>s+x,0))}</b></td></tr>`}).join('');const ok=c.sync==='Sincronizado';openModal(`Pauta ${c.id} · ${c.client}`,`<p class="modal-intro">El sistema reparte las ${num(target)} reproducciones contratadas entre las ${n} pantallas del plan ${esc(c.plan)} y las cinco franjas de operación, con más peso en las horas de mayor tráfico.</p><div class="pauta-stats"><div><span>Creativo</span><b>${esc(c.creative||'Pendiente')}</b></div><div><span>Entregadas</span><b>${num(c.plays||0)} de ${num(target)}</b></div><div><span>Por pantalla</span><b>${num(porPantalla)}</b></div><div><span>OnSign</span><b>${ok?'Sincronizada':'Pendiente de envío'}</b></div></div><div class="pauta-table-wrap"><table class="pauta-table"><thead><tr><th>Pantalla</th>${franjas.map(f=>`<th>${f[0]}</th>`).join('')}<th>Total</th></tr></thead><tbody>${filas}</tbody></table></div><div class="form-submit"><span>${ok?'La distribución ya está en OnSign. Cualquier cambio se vuelve a enviar con un clic.':'Revisa la distribución y envíala a OnSign.'}</span>${ok?'<button class="button outline" data-action="close-modal">Cerrar</button>':`<button class="button primary" data-action="sync-modal" data-id="${esc(c.id)}">Enviar a OnSign</button>`}</div>`,true)}
function campaignModal(){openModal('Crear pauta',`<p class="modal-intro">Registra lo contratado y prepara una distribución por pantalla y hora.</p><form id="campaign-form" class="form-grid"><label class="field-label span-two">CLIENTE<select name="client">${CLIENTS.map(c=>`<option ${c.name==='Bambito'?'selected':''}>${esc(c.name)}</option>`).join('')}<option>Nuevo cliente de ejemplo</option></select></label><label class="field-label">CREATIVO<input name="creative" value="campana-diciembre.mp4" required></label><label class="field-label">PLAN<select name="plan">${PLANS.map(p=>`<option value="${p.id}">${p.id} · ${p.screens} ${p.screens===1?'pantalla':'pantallas'}</option>`).join('')}</select></label><label class="field-label">REPRODUCCIONES CONTRATADAS<input name="target" type="number" min="100" value="45000" required></label><label class="field-label">FECHA DE INICIO<input name="start" type="date" value="${monthValue()}-01"></label><label class="field-label">FECHA DE CIERRE<input name="end" type="date" value="${monthValue()}-30"></label><label class="field-label">ZONA PREFERIDA<select name="zone">${ZONES.map(z=>`<option>${z}</option>`).join('')}</select></label><label class="field-label">HORARIO<select name="hours"><option>Todo el día</option><option>6 a. m. a 12 p. m.</option><option>12 p. m. a 6 p. m.</option><option>3 p. m. a 9 p. m.</option></select></label><div class="form-submit span-two"><span>Distribución calculada al guardar · Conexión OnSign de demostración</span><button class="button primary">Crear y distribuir pauta</button></div></form>`)}
function clientModal(id){const c=CLIENTS.find(x=>x.id===id);if(!c)return;openModal(c.name,`<div class="client-detail-head"><div><span class="kicker">${esc(c.stage.toUpperCase())} · ${esc(c.plan)}</span><h3>${esc(c.contact)}</h3><p>${esc(c.email)} · ${esc(c.phone)}</p></div><button class="button outline" data-action="new-message" data-ref="${esc(c.name)}">Escribir al equipo</button></div><div class="detail-stat-grid"><div><span>Tiempo pautando</span><strong>${c.stage==='Activo'?'Campaña mensual':'Sin pauta activa'}</strong></div><div><span>Pagado en noviembre</span><strong>${money(c.stage==='Activo'?c.revenue*.82:0)}</strong></div><div><span>Campaña actual</span><strong>${esc(c.campaign||'No aplica')}</strong></div><div><span>Creativo</span><strong>${esc(c.creative||'Pendiente')}</strong></div></div><div class="detail-two"><section><span class="kicker">CAMPAÑAS</span><div class="timeline-record"><b>${esc(c.campaign||'Registro comercial')}</b><small>${esc(c.period||'En preparación')} · ${esc(c.plan)} · ${num(c.plays)} reproducciones</small></div><div class="timeline-record"><b>Historial</b><small>${esc(c.history)} · ${money(c.revenue)} registrados</small></div><span class="kicker">LLAMADAS Y MENSAJES</span><div class="timeline-record"><b>Resumen de llamada · 6 nov</b><small>Conversaron sobre cobertura por zona, duración de pauta y medición del QR.</small></div><details class="transcript-details"><summary>Ver transcripción de llamada</summary><p><b>${esc(c.contact)}:</b> Queremos priorizar las zonas cercanas a nuestras sucursales y entender cuántas personas llegan desde el QR.</p><p><b>MOVIADS:</b> Podemos documentar reproducciones por equipo y presentar los escaneos y acciones del QR en el reporte mensual.</p></details><div class="timeline-record"><b>Correo · 12 nov</b><small>${esc(c.contact)} solicita el resumen de cobertura y el creativo aprobado.</small></div><div class="timeline-record"><b>WhatsApp · ${esc(c.contact)}</b><small>Cliente solicita revisar resultados al cierre de mes. ${c.messages} mensajes vinculados.</small></div><div class="timeline-record"><b>Factura vinculada</b><small>${c.stage==='Activo'?`FV-2026-${String(CLIENTS.indexOf(c)+441).padStart(4,'0')} · ${money(c.revenue)}`:'Sin factura activa'}</small></div><div class="client-detail-actions">${c.stage==='Activo'?`<button class="text-link" data-action="invoice" data-id="${c.id}">Abrir factura ↗</button>`:''}<button class="text-link" data-action="thread-ref" data-ref="${esc(c.name)}">Abrir mensajes internos ↗</button></div></section><aside class="client-detail-side"><span class="kicker">MEDICIÓN</span><strong>${num(c.plays)}</strong><small>reproducciones entregadas</small><div class="progress-line"><i style="width:${c.target?Math.min(100,c.plays/c.target*100):0}%"></i></div><div class="side-metric"><span>Escaneos QR</span><b>${num(c.scans)}</b></div><div class="side-metric"><span>Acciones</span><b>${num(c.actions)}</b></div><div class="side-metric"><span>Factura</span><b>${money(c.revenue)}</b></div><button class="button primary full" data-action="report" data-client="${esc(c.name)}">Generar reporte</button></aside></div>` ,true)}
function leadModal(id){const l=LEADS.find(x=>x.id===id);if(!l)return;openModal(l.name,`<div class="lead-detail-title"><div><span class="kicker">${esc(l.sector)} · ${esc(l.zone)}</span><h3>${esc(l.person)}</h3></div><span class="lead-heat">${esc(state.leadHeat[l.id]||l.heat)}</span></div><div class="lead-conversation">${l.messages.map((m,i)=>`<div class="chat-message ${i%2?'incoming':''}"><small>${i%2?esc(l.name):'MOVIADS Central'}</small><p>${esc(m.split(': ').slice(1).join(': '))}</p></div>`).join('')}</div><div class="lead-brief"><div><span>Qué busca</span><strong>${esc(l.intent)}</strong></div><div><span>Segundos</span><strong>${l.seconds||'Por definir'}</strong></div><div><span>Zonas</span><strong>${esc(l.zone)}</strong></div><div><span>Presupuesto</span><strong>${l.budget?money(l.budget):'Por conversar'}</strong></div></div><div class="lead-modal-actions"><button class="button outline" data-action="new-message" data-ref="${esc(l.name)}">Consultar al equipo</button>${(state.autonomy[state.profile]||profile().autonomy)==='Consultar antes de escribir'?`<button class="button primary" data-action="approve-lead" data-id="${l.id}">Aprobar próximo mensaje</button>`:`<button class="button primary" data-action="approve-lead" data-id="${l.id}">Ver próximo paso</button>`}</div>`)}
function unitModal(id){const f=FLEET.find(x=>x.id===id);if(!f)return;openModal(`Unidad ${f.id}`,`<div class="unit-detail"><img src="./assets/${f.image}" alt="Vehículo de flota"><div><span class="kicker">${esc(f.car)}</span><h3>${esc(f.driver)}</h3><div class="screen-state ${f.status}"><i></i>${f.status==='online'?'Pantalla encendida':f.status==='off'?'Pantalla apagada':'Sin señal'}</div></div></div><div class="detail-stat-grid"><div><span>Horas activas hoy</span><strong>${f.hours.toFixed(1)} h</strong></div><div><span>Kilómetros registrados</span><strong>${num(f.km)} km</strong></div><div><span>Zona reciente</span><strong>${esc(f.zone)}</strong></div><div><span>Incentivo mensual</span><strong>${money(f.incentive)}</strong></div></div><div class="timeline-record"><b>Comportamiento del conductor</b><small>${esc(f.behavior)} · Métrica ilustrativa según recorridos registrados.</small></div><button class="button outline" data-action="ask-accountant" data-amount="Incentivo ${f.driver} · ${money(f.incentive)}">Preguntar al contable ↗</button>`)}
function reportModal(name){const c=CLIENTS.find(x=>x.name===name)||CLIENTS[0];openModal(`Reporte de ${c.name}`,`<div class="report-preview" id="report-print"><header><img src="./assets/logo-moviads.svg" alt="MOVIADS"><span>REPORTE DE CAMPAÑA · NOVIEMBRE 2026</span></header><h3>${esc(c.name)}</h3><p>${esc(c.campaign||'Resumen de actividad')} · ${esc(c.period||'Noviembre 2026')}</p><div class="report-kpis"><div><strong>${num(c.plays)}</strong><span>reproducciones</span></div><div><strong>${num(c.scans)}</strong><span>escaneos QR</span></div><div><strong>${num(c.actions)}</strong><span>acciones</span></div><div><strong>${c.zones.length}</strong><span>zonas cubiertas</span></div></div><div class="report-map"><svg viewBox="0 0 800 180"><path d="M18 137 C142 110 195 120 283 82 S424 110 510 58 S675 73 783 22" fill="none" stroke="#173A7A" stroke-width="3"/>${c.zones.map((z,i)=>`<circle cx="${40+i*95}" cy="${130-(i%3)*38}" r="5" fill="#15A595"/><text x="${40+i*95}" y="${154-(i%3)*38}" font-size="11" fill="#4F5867">${esc(z)}</text>`).join('')}</svg></div><div class="report-foot"><span>Comparativo mensual</span><strong>+8.4% reproducciones frente a octubre</strong><small>Registro de fecha, hora, equipo y coordenada GPS disponible para auditoría.</small></div></div><div class="modal-actions"><button class="button outline" data-action="report-csv" data-client="${esc(c.name)}">Descargar Excel · CSV</button><button class="button primary" data-action="print-report">Imprimir / guardar PDF</button></div>` ,true)}
function invoiceModal(c){const numId=`FV-2026-${String(CLIENTS.indexOf(c)+441).padStart(4,'0')}`;const generated=state.invoices.find(x=>x.client===c.name);const ref=generated?.cufe||'CUFE-DMO-26-0000-0000-0000-0000';openModal(`Factura · ${c.name}`,`<div class="invoice-document" id="invoice-print"><header><img src="./assets/logo-moviads.svg" alt="MOVIADS"><div><b>FACTURA ELECTRÓNICA</b><span>DOCUMENTO DE DEMOSTRACIÓN</span></div></header><div class="invoice-doc-id"><span>${numId}</span><span>Fecha de emisión · 18 nov 2026</span></div><div class="invoice-billto"><span>FACTURAR A</span><strong>${esc(c.name)}</strong><small>${esc(c.contact)} · Panamá</small></div><div class="invoice-line"><span>Campaña de publicidad digital exterior · ${esc(c.plan)}</span><strong>${money(c.revenue)}</strong></div><div class="invoice-total"><span>Total USD</span><strong>${money(c.revenue)}</strong></div><div class="cufe-block"><div><span>CUFE DE EJEMPLO</span><b>${ref}</b><small>No válido para trámite fiscal</small></div><div class="qr-fake" aria-label="Código QR ilustrativo">${Array.from({length:64},(_,i)=>`<i style="opacity:${(i*11%7)/8+.12}"></i>`).join('')}</div></div></div><div class="modal-actions"><button class="button outline" data-action="print-invoice">Imprimir / guardar PDF</button><button class="button primary" data-action="invoice-done" data-id="${c.id}">${generated?'Listo':'Marcar como emitida'}</button></div><p class="footnote">Representación ilustrativa. No está autorizada por la DGI.</p>`)}
function assistantModal(){openModal('Asistente MOVIADS',`<div class="assistant-box"><div class="assistant-greeting"><span class="assistant-glyph">⌕</span><div><strong>Pregunta sobre la operación</strong><small>Responde con los datos de la red, los clientes y las finanzas.</small></div></div><div class="assistant-suggestions"><button data-question="Qué pantallas tengo libres en diciembre">¿Qué pantallas tengo libres en diciembre?</button><button data-question="Cuánto facturó McDonald's este año">¿Cuánto facturó McDonald’s este año?</button><button data-question="Cuántos escaneos tuvo Tropigas">¿Cuántos escaneos tuvo Tropigas?</button></div><div id="assistant-response" class="assistant-response">Prueba una pregunta sugerida o escribe una consulta.</div><form id="assistant-form"><input id="assistant-input" placeholder="Escribe tu pregunta" autocomplete="off"><button class="button primary">Consultar</button></form></div>`)}
function ruleModal(){const r=state.rules||{maxMessages:true,stopNegative:true,checkPrice:true,days:'2 días'};openModal('Reglas del agente',`<p class="modal-intro">Estas reglas se aplican a las conversaciones de demostración.</p><form id="rules-form" class="rules-form"><label><input name="maxMessages" type="checkbox" ${r.maxMessages?'checked':''}> Máximo 2 mensajes por lead al día</label><label><input name="stopNegative" type="checkbox" ${r.stopNegative?'checked':''}> Detener contacto al recibir una respuesta negativa</label><label><input name="checkPrice" type="checkbox" ${r.checkPrice?'checked':''}> Consultar antes de ofrecer precio no aprobado</label><label class="field-label">DÍAS ENTRE SEGUIMIENTOS<select name="days">${['2 días','3 días','5 días'].map(x=>`<option ${x===r.days?'selected':''}>${x}</option>`).join('')}</select></label><button class="button primary">Guardar reglas</button></form>`)}
function newMessageModal(ref=''){openModal('Nuevo mensaje interno',`<form id="new-message-form" class="form-grid"><label class="field-label">PARA<select name="to">${['Ana Victoria','Eric','Emanuel','Ventas','Contabilidad','Atención al cliente'].filter(n=>n!==profile().name).map(n=>`<option ${ref&&n==='Contabilidad'?'selected':''}>${n}</option>`).join('')}</select></label><label class="field-label">VINCULAR A<select name="ref">${[ref||'Clínica Sonrisa','Tropigas','McDonald’s','Pantalla MA-07','Combustible · noviembre'].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field-label span-two">ASUNTO<input name="subject" value="Revisar ${esc(ref||'registro')}" required></label><label class="field-label span-two">MENSAJE<textarea name="body" placeholder="Escribe un mensaje para tu equipo" required></textarea></label><div class="form-submit span-two"><button class="button primary">Enviar mensaje</button></div></form>`)}
function notifyModal(){openModal('Aviso de prospección',`<div class="whatsapp-preview"><div class="wa-head">MOVIADS · aviso de agente</div><p>Encontré esta panadería en Obarrio. Le escribo para compartirle la cobertura disponible?</p><small>Panadería Masa · Obarrio · WhatsApp</small></div><div class="modal-actions"><button class="button outline" data-action="notice-no">No, omitir</button><button class="button primary" data-action="notice-yes">Sí, escribir</button></div><p class="footnote">La acción solo actualiza esta simulación. No se envía un mensaje real.</p>`)}
function getAnswer(q){const s=q.toLowerCase();if(s.includes('libre')||s.includes('pantalla')){let m=s.includes('diciembre')?`${today.getFullYear()}-12`:state.month;return `En ${monthName(m)} hay ${160-soldCount(m)-reservedCount(m)} espacios libres de 160. La red tiene 20 pantallas y 8 espacios por loop.`}if(s.includes('mcdonald')){const c=CLIENTS.find(x=>x.name.includes('McDonald'));return `McDonald’s registra ${money(c.revenue)} en noviembre dentro de los datos de ejemplo. La facturación acumulada en el historial incluido es ${money(c.revenue*6)}.`}if(s.includes('tropigas')){const c=CLIENTS[0];return `Tropigas registra ${num(c.scans)} escaneos QR y ${num(c.actions)} acciones finales en noviembre. La campaña lleva ${num(c.plays)} reproducciones.`}if(s.includes('cobrar')||s.includes('factura'))return `El saldo pendiente estimado en la muestra es ${money(pendingReceivable())}, distribuido entre 4 facturas.`;return 'Puedo consultar ocupación de pantallas, actividad de clientes, escaneos QR y cifras de ejemplo. Prueba una pregunta sugerida.'}
function exportCsv(name){const c=CLIENTS.find(x=>x.name===name)||CLIENTS[0];const rows=[['MOVIADS Central','Reporte de campaña','Noviembre 2026'],['Cliente',c.name],['Campaña',c.campaign],['Reproducciones',c.plays],['Escaneos QR',c.scans],['Acciones',c.actions],['Zonas',c.zones.join(' | ')],['Comparativo','+8.4% vs octubre']];const csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n');download(csv,`reporte-${c.id}-noviembre.csv`,'text/csv;charset=utf-8')}
function download(data,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportAll(){const content={exportedAt:new Date().toISOString(),label:'Datos de ejemplo MOVIADS Central',state,clients:CLIENTS,leads:LEADS,fleet:FLEET};download(JSON.stringify(content,null,2),'moviads-central-datos.json','application/json')}
function showGate(){const gate=$('#gate');gate.hidden=false;gate.innerHTML=`<section class="gate-photo"><img src="./assets/carro-aereo.jpg" alt="Vehículo con pantalla LED MOVIADS"><div class="gate-shade"></div><div class="gate-wordmark"><img src="./assets/logo-moviads.svg" alt=""><b>MOVIADS</b><span>Central</span></div><div class="gate-photo-caption"><span>PUBLICIDAD DIGITAL EXTERIOR</span><h1>La red en movimiento.<br>La operación en un solo lugar.</h1><p>Plataforma de gestión para la red de pantallas MOVIADS.</p></div><span class="gate-photo-foot">CIUDAD DE PANAMÁ · 20 UNIDADES EN RED</span></section><section class="gate-form-side"><div class="gate-form"><span class="kicker">ACCESO A LA PLATAFORMA</span><h2>MOVIADS Central</h2><p>Ingresa la clave de acceso para abrir el prototipo.</p><form id="gate-form"><label class="field-label" for="gate-password">CLAVE DE ACCESO</label><input id="gate-password" type="password" placeholder="Escriba la clave" autocomplete="current-password"><button class="button primary full">Entrar al sistema</button><div id="gate-error" role="alert"></div></form><small class="gate-note">Prototipo navegable · Datos de ejemplo</small></div><div class="gate-foot">MOVIADS · CIUDAD DE PANAMÁ</div></section>`;$('#app').innerHTML='';}

function start(){const params=new URLSearchParams(location.search),host=location.hostname;const local=['localhost','127.0.0.1','::1'].includes(host);const cap=local&&params.get('cap');if(cap){const v=MODULES.find(x=>x[0]===cap||x[1].toLowerCase()===cap.toLowerCase());if(v)state.view=v[0];const who=allProfiles().find(p=>p.id===params.get('perfil'));if(who)state.profile=who.id;sessionStorage.setItem('moviads-auth','yes');save();render();return;}if(sessionStorage.getItem('moviads-auth')==='yes'){render();return;}showGate();}

document.addEventListener('click',e=>{
 const view=e.target.closest('[data-view]');if(view){e.preventDefault();state.view=view.dataset.view;save();render();window.scrollTo({top:0,behavior:'smooth'});return;}
 const filter=e.target.closest('[data-filter]');if(filter){$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===filter));$$('[data-client-row]').forEach(row=>row.hidden=filter.dataset.filter!=='all'&&row.dataset.stage!==filter.dataset.filter);return;}
 const fleetFilter=e.target.closest('[data-fleet-filter]');if(fleetFilter){$$('[data-fleet-filter]').forEach(x=>x.classList.toggle('active',x===fleetFilter));$$('[data-fleet-item]').forEach(row=>row.hidden=fleetFilter.dataset.fleetFilter!=='all'&&row.dataset.status!==fleetFilter.dataset.fleetFilter);return;}
 const q=e.target.closest('[data-question]');if(q){const answer=getAnswer(q.dataset.question);const box=$('#assistant-response');if(box)box.innerHTML=`<b>${esc(q.dataset.question)}</b><p>${esc(answer)}</p>`;return;}
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='close-modal'){if(e.target===b||b.classList.contains('icon-btn'))closeModal();return;}
 if(a==='assistant'){assistantModal();return;}if(a==='sale'){saleModal();updateSaleAvailability();return;}if(a==='campaign'){campaignModal();return;}if(a==='reset'){if(confirm('¿Restablecer todos los datos de ejemplo y los cambios de esta sesión?')){localStorage.removeItem(KEY);state=fresh();save();render();toast('Datos de ejemplo restablecidos');}return;}
 if(a==='decision'){state.decisions[b.dataset.id]=b.dataset.value;save();if(b.dataset.value==='Aprobada'&&b.dataset.go)state.view=b.dataset.go;save();render();toast(`Propuesta ${b.dataset.value.toLowerCase()}`);return;}
 if(a==='slot'){const row=ensureMonth(state.month)[b.dataset.unit],slot=Number(b.dataset.slot),item=row[slot];openModal(`${b.dataset.unit} · Espacio ${String(slot+1).padStart(2,'0')}`,item?`<div class="slot-detail"><span class="slot-state ${item.kind}">${item.kind}</span><h3>${esc(item.client)}</h3><p>Plan ${esc(item.plan)} · período ${esc(monthName(state.month))}</p></div><button class="button outline" data-action="client" data-id="${CLIENTS.find(c=>c.name===item.client)?.id||'c1'}">Abrir cliente ↗</button>`:`<div class="slot-detail"><span class="slot-state free">Libre</span><h3>Disponible para reservar</h3><p>Este espacio puede incluirse en una venta del período.</p></div><button class="button outline" data-action="reserve-slot" data-unit="${b.dataset.unit}" data-slot="${slot}">Reservar espacio</button><button class="button primary" data-action="sale">Simular venta +</button>`);return;}
 if(a==='reserve-slot'){ensureMonth(state.month)[b.dataset.unit][Number(b.dataset.slot)]={client:'Reserva temporal',plan:'Pendiente',kind:'reservado'};save();closeModal();render();toast('Espacio reservado');return;}
 if(a==='pauta'){pautaModal(b.dataset.id);return;}if(a==='sync-modal'){state.sync[b.dataset.id]='Sincronizado';save();render();pautaModal(b.dataset.id);toast('Pauta enviada a OnSign');return;}if(a==='sync'){const id=b.dataset.id;state.sync[id]=state.sync[id]==='Sincronizado'?'Pendiente de envío':'Sincronizado';save();render();toast(state.sync[id]==='Sincronizado'?'Pauta enviada a OnSign':'Sincronización pausada');return;}
 if(a==='client'){clientModal(b.dataset.id);return;}if(a==='report'){reportModal(b.dataset.client);return;}if(a==='lead-detail'){leadModal(b.dataset.id);return;}if(a==='unit'){unitModal(b.dataset.id);return;}if(a==='integration'){openModal(b.dataset.name,`<p class="modal-intro">Esta conexión está representada en el prototipo. Para usarla se requiere habilitar el acceso y configurar la integración de MOVIADS.</p><div class="integration-detail"><span class="kicker">ESTADO ACTUAL</span><strong>${esc(state.sync[b.dataset.name]||INTEGRATIONS.find(x=>x.name===b.dataset.name)?.state)}</strong><span>Última actividad · ${esc(INTEGRATIONS.find(x=>x.name===b.dataset.name)?.last||'No sincronizado')}</span></div><button class="button outline" data-action="integration-enable" data-name="${esc(b.dataset.name)}">${b.dataset.name.includes('OnSign')?'Probar sincronización':'Marcar como conectada'}</button>`);return;}
 if(a==='integration-enable'){state.sync[b.dataset.name]='Conectada en la demostración';save();closeModal();render();toast(`${b.dataset.name}: estado actualizado`);return;}
 if(a==='agent-type'){state.agentType=b.dataset.value;render();return;}if(a==='run-agent'){const drivers=state.agentType==='conductores',zone=$('#agent-zone')?.value||'la zona seleccionada';const records=drivers?[['Luis Pérez','Juan Díaz · Interesado en incentivo de flota'],['Marcos Gómez','Tocumen · Disponibilidad de tarde'],['Conductor de plataforma · A. R.','San Miguelito · Sin respuesta todavía']]:[['Centro Dental Obarrio','Obarrio · Interés por campañas con QR'],['Consultorio Sonríe','Obarrio · Solicita información de cobertura'],['Dental Care Panamá','Obarrio · Sin respuesta todavía']];openModal('Búsqueda preparada',`<p class="modal-intro">El agente preparó 3 registros de ejemplo para ${esc($('#agent-sector')?.value||'el rubro seleccionado')} en ${esc(zone)}.</p>${records.map(x=>`<div class="timeline-record"><b>${x[0]}</b><small>${x[1]}</small></div>`).join('')}<button class="button primary" data-action="close-modal">Cerrar</button>`);return;}if(a==='simulate-notice'){notifyModal();return;}if(a==='notice-no'){closeModal();toast('El agente omitió el contacto');return;}if(a==='notice-yes'){closeModal();state.leadHeat.l2='Tibio';save();toast('Contacto aprobado en la simulación');return;}if(a==='agent-rules'){ruleModal();return;}if(a==='approve-lead'){closeModal();toast('Siguiente paso registrado en la simulación');return;}
 if(a==='invoice'){const c=CLIENTS.find(x=>x.id===b.dataset.id);if(c)invoiceModal(c);return;}if(a==='invoice-view'){const c=CLIENTS.find(x=>x.id===b.dataset.id);if(c)invoiceModal(c);return;}if(a==='invoice-done'){const c=CLIENTS.find(x=>x.id===b.dataset.id);if(c&&!state.invoices.some(x=>x.client===c.name)){state.invoices.push({client:c.name,cufe:`CUFE-DMO-${c.id.toUpperCase()}-2026`});save();}closeModal();toast('Factura marcada como emitida en la demostración');render();return;}
 if(a==='print-report'||a==='print-invoice'){window.print();return;}if(a==='report-csv'){exportCsv(b.dataset.client);toast('Reporte CSV descargado');return;}
 if(a==='ask-accountant'){const ref=b.dataset.amount;newMessageModal(ref);return;}if(a==='new-message'){newMessageModal(b.dataset.ref||'');return;}if(a==='thread'){const item=[...state.messages,...state.threads].find(x=>x.id===b.dataset.id);if(item)openModal(item.subject,`<p class="modal-intro">${esc(item.from)} · ${esc(item.time)} · ${esc(item.ref)}</p><div class="message-bubble"><p>${esc(item.body)}</p></div><button class="button primary" data-action="new-message" data-ref="${esc(item.ref)}">Responder al hilo</button>`);return;}if(a==='thread-ref'){closeModal();state.view='mensajes';save();render();return;}
 if(a==='export-all'){exportAll();toast('Archivo de datos descargado');return;}if(a==='add-user'){openModal('Agregar usuario',`<form id="user-form" class="form-grid"><label class="field-label">NOMBRE<input name="name" placeholder="Nombre y apellido" required></label><label class="field-label">CORREO<input name="email" type="email" placeholder="nombre@empresa.com" required></label><label class="field-label">ROL<select name="role"><option>Ventas</option><option>Contabilidad</option><option>Atención al cliente</option><option>Personalizado</option></select></label><div class="form-submit"><button class="button primary">Crear usuario de ejemplo</button></div></form>`);return;}if(a==='user-access'){const p=allProfiles().find(x=>x.id===b.dataset.id);if(p)openModal(`Permisos · ${p.name}`,`<p class="modal-intro">Rol asignado: ${esc(p.role)}. Los perfiles de ejemplo muestran los permisos configurados para cada función.</p><div class="timeline-record"><b>Datos financieros</b><small>${p.access==='owner'||p.access==='finance'?'Puede consultar según el rol':'Sin acceso a margen y costos'}</small></div><div class="timeline-record"><b>Exportar datos</b><small>${p.access==='owner'||p.access==='finance'?'Disponible':'No disponible en este perfil'}</small></div><div class="timeline-record"><b>Autonomía del agente</b><small>${esc(state.autonomy[p.id]||p.autonomy)} · Avisos por ${esc(p.channel)}</small></div>`);return;}
 if(a==='notice-no'||a==='notice-yes')return;
});

function updateSaleAvailability(){const f=$('#sale-form');if(!f)return;const plan=PLANS.find(p=>p.id===f.elements.plan.value);$('#sale-availability').textContent=`${packageAvailable(plan,f.elements.month.value)} paquetes ${plan.id}`;}
document.addEventListener('change',e=>{
 if(e.target.id==='profile-select'){state.profile=e.target.value;const p=profile();state.view=p.access==='finance'?'finanzas':'inicio';save();render();return;}
 if(e.target.id==='inventory-month'){state.month=e.target.value||monthValue();ensureMonth(state.month);save();render();return;}
 if(e.target.id==='customer-select'){state.customer=e.target.value;save();render();return;}
 if(e.target.id==='autonomy-select'){state.autonomy[state.profile]=e.target.value;save();toast('Autonomía actualizada para '+profile().name);render();return;}
 if(e.target.id==='notice-channel'){state.channels=state.channels||{};state.channels[state.profile]=e.target.value;save();toast(`Avisos por ${e.target.value}`);return;}
 if(e.target.matches('[data-lead-heat]')){state.leadHeat[e.target.dataset.leadHeat]=e.target.value;save();render();toast('Clasificación del lead actualizada');return;}
 if(e.target.matches('[data-filter]')){$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===e.target));$$('[data-client-row]').forEach(row=>row.hidden=e.target.dataset.filter!=='all'&&row.dataset.stage!==e.target.dataset.filter);return;}
 if(e.target.matches('[data-fleet-filter]')){$$('[data-fleet-filter]').forEach(x=>x.classList.toggle('active',x===e.target));$$('[data-fleet-item]').forEach(row=>row.hidden=e.target.dataset.fleetFilter!=='all'&&row.dataset.status!==e.target.dataset.fleetFilter);return;}
 if(e.target.closest('#sale-form')&&['month','plan'].includes(e.target.name)){updateSaleAvailability();return;}
});
document.addEventListener('input',e=>{if(e.target.id==='client-search'){const q=e.target.value.toLowerCase();$$('[data-client-row]').forEach(r=>r.hidden=!r.dataset.name.includes(q));}if(e.target.id==='fleet-search'){const q=e.target.value.toLowerCase();$$('[data-fleet-item]').forEach(r=>r.hidden=!r.dataset.search.includes(q));}});
document.addEventListener('submit',e=>{
 e.preventDefault();const f=e.target;
 if(f.id==='gate-form'){if($('#gate-password').value.trim().toUpperCase()===PASS){sessionStorage.setItem('moviads-auth','yes');const g=$('#gate');g.hidden=true;g.innerHTML='';render();window.scrollTo(0,0);}else $('#gate-error').textContent='La clave no coincide. Intenta de nuevo.';return;}
 if(f.id==='sale-form'){const data=new FormData(f),m=String(data.get('month')),plan=PLANS.find(x=>x.id===data.get('plan'));state.month=m;const allocations=allocationFor(plan.id,m);if(allocations.length<plan.screens){toast('No hay espacios suficientes para ese plan en el período.');return;}const client=String(data.get('client'));for(const [unit,slot] of allocations)ensureMonth(m)[unit][slot]={client,plan:plan.id,kind:'vendido'};state.sales.push({client,plan:plan.id,month:m,value:Number(data.get('value')),start:data.get('start'),end:data.get('end')});save();closeModal();render();toast(`${plan.id} reservado en ${monthName(m)}`);return;}
 if(f.id==='campaign-form'){const d=new FormData(f),id=`PA-${String(100+state.campaigns.length).padStart(3,'0')}`,target=Number(d.get('target')),plan=PLANS.find(x=>x.id===d.get('plan')),client=d.get('client'),m=String(d.get('start')).slice(0,7),map=ensureMonth(m),existing=Object.values(map).flat().filter(x=>x&&x.client===client&&x.plan===plan.id).length,needed=Math.max(0,plan.screens-existing),slots=allocationFor(plan.id,m).slice(0,needed);if(slots.length<needed){toast('No hay espacios suficientes para distribuir esta pauta en el período.');return;}for(const [unit,slot] of slots)map[unit][slot]={client,plan:plan.id,kind:'reservado'};state.month=m;state.campaigns.unshift({id,client,creative:d.get('creative'),plays:0,target,plan:plan.id,sync:'Pendiente de envío',progress:0,zone:d.get('zone'),hours:d.get('hours'),month:m,value:0});save();closeModal();state.view='programacion';render();toast('Pauta creada, espacios reservados y distribución preparada');return;}
 if(f.id==='message-form'){const body=$('#message-input').value,ref=$('#message-ref').value;state.threads.unshift({id:`t${Date.now()}`,from:profile().name,to:'Equipo MOVIADS',subject:`Seguimiento · ${ref}`,body,ref,time:'Ahora'});save();render();toast('Mensaje enviado al equipo');return;}
 if(f.id==='new-message-form'){const d=new FormData(f);state.threads.unshift({id:`t${Date.now()}`,from:profile().name,to:d.get('to'),subject:d.get('subject'),body:d.get('body'),ref:d.get('ref'),time:'Ahora'});save();closeModal();state.view='mensajes';render();toast('Mensaje interno enviado');return;}
 if(f.id==='assistant-form'){const q=$('#assistant-input').value;$('#assistant-response').innerHTML=`<b>${esc(q)}</b><p>${esc(getAnswer(q))}</p>`;return;}
 if(f.id==='rules-form'){state.rules={maxMessages:f.elements.maxMessages.checked,stopNegative:f.elements.stopNegative.checked,checkPrice:f.elements.checkPrice.checked,days:f.elements.days.value};save();closeModal();toast('Reglas de demostración guardadas');return;}
 if(f.id==='user-form'){const d=new FormData(f),role=d.get('role'),access=role==='Ventas'?'sales':role==='Contabilidad'?'finance':role==='Atención al cliente'?'service':'service';state.extraUsers=state.extraUsers||[];state.extraUsers.push({id:`user-${Date.now()}`,name:d.get('name'),role,access,autonomy:'Consultar antes de escribir',channel:'WhatsApp'});save();closeModal();render();toast('Usuario agregado');return;}
});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();assistantModal();}if(e.key==='Escape')closeModal();});
start();
